## Submitted testbench
```systemverilog
`timescale 1ns / 1ps

module tb;

  localparam int        CLK_PERIOD = 8;
  localparam logic [15:0] PRESCALE = 16'd5;
  localparam int        BIT_CLKS   = 40;

  logic         clk = 1'b0;
  logic         rst = 1'b0;

  logic [7:0]   s_axis_tdata = 8'h00;
  logic         s_axis_tvalid = 1'b0;
  wire          s_axis_tready;

  wire  [7:0]   m_axis_tdata;
  wire          m_axis_tvalid;
  logic         m_axis_tready = 1'b0;

  logic         rxd = 1'b1;
  wire          txd;

  wire          tx_busy;
  wire          rx_busy;
  wire          rx_overrun_error;
  wire          rx_frame_error;

  logic [15:0]  prescale = PRESCALE;

  always #(CLK_PERIOD / 2) clk = ~clk;

  uart dut (
    .clk(clk),
    .rst(rst),

    .s_axis_tdata(s_axis_tdata),
    .s_axis_tvalid(s_axis_tvalid),
    .s_axis_tready(s_axis_tready),

    .m_axis_tdata(m_axis_tdata),
    .m_axis_tvalid(m_axis_tvalid),
    .m_axis_tready(m_axis_tready),

    .rxd(rxd),
    .txd(txd),

    .tx_busy(tx_busy),
    .rx_busy(rx_busy),
    .rx_overrun_error(rx_overrun_error),
    .rx_frame_error(rx_frame_error),

    .prescale(prescale)
  );

  task automatic wait_clks(input int n);
    repeat (n) @(negedge clk);
  endtask

  task automatic do_reset();
    rst = 1'b1;
    wait_clks(4);
    rst = 1'b0;
    wait_clks(4);
  endtask

  task automatic send_good(input logic [7:0] d);
    @(negedge clk);
    rxd = 1'b0;
    wait_clks(BIT_CLKS);
    for (int i = 0; i < 8; i++) begin
      rxd = d[i];
      wait_clks(BIT_CLKS);
    end
    rxd = 1'b1;
    wait_clks(BIT_CLKS);
  endtask

  // Bad 8N1 frame: stop bit is low.
  task automatic send_bad(input logic [7:0] d);
    @(negedge clk);
    rxd = 1'b0;
    wait_clks(BIT_CLKS);
    for (int i = 0; i < 8; i++) begin
      rxd = d[i];
      wait_clks(BIT_CLKS);
    end
    rxd = 1'b0;
    wait_clks(BIT_CLKS);
    rxd = 1'b1;
    wait_clks(1);
  endtask

  task automatic wait_rx_idle_stable();
    int cnt;
    cnt = 0;
    forever begin
      @(negedge clk);
      if (!rx_busy) begin
        cnt = cnt + 1;
        if (cnt >= 2) return;
      end else begin
        cnt = 0;
      end
    end
  endtask

  task automatic wait_pending_3c();
    forever begin
      @(negedge clk);
      if (m_axis_tvalid && !m_axis_tready && (m_axis_tdata == 8'h3C)) return;
    end
  endtask

  initial begin
    m_axis_tready = 1'b0;
    s_axis_tvalid = 1'b0;
    s_axis_tdata  = 8'h00;
    rxd           = 1'b1;
    prescale      = PRESCALE;

    do_reset();

    // First word 0x3C is received while the sink is stalled.
    send_good(8'h3C);
    wait_pending_3c();
    wait_rx_idle_stable();
    wait_clks(4);

    // Cause a frame error while 0x3C is still held under back-pressure.
    send_bad(8'h5A);
    wait_rx_idle_stable();
    wait_clks(4);

    // Ensure the stalled word is still present before the overrun frame.
    wait_pending_3c();
    wait_rx_idle_stable();

    // A good 0xA5 frame completes and overruns the stalled 0x3C.
    send_good(8'hA5);

    // Let the overrun pulse be sampled by the cover property.
    wait_clks(4 * BIT_CLKS);

    $display("R26 sequence complete");
    $finish;
  end

  initial begin
    #1ms;
    $finish;
  end

endmodule
```

